func:
// ========================================================
// Simula a dinâmica contínua de chuva e escoamento urbano
// ========================================================
let waterLevel = flow.get("sim_water_level") || 30.0;
let delta = flow.get("sim_delta") || 3.5;

// Incremento estocástico
waterLevel += delta + (Math.random() * 1.0 - 0.5);

// Ciclo de transbordamento e escoamento
if (waterLevel >= 185.0) {
    delta = -4.5; // Calha cheia: inicia escoamento
} else if (waterLevel <= 25.0) {
    delta = 4.0;  // Calha vazia: nova chuva se inicia
}

flow.set("sim_water_level", waterLevel);
flow.set("sim_delta", delta);

let totalDepth = 200.0;
let dist = Math.max(5.0, Math.min(200.0, totalDepth - waterLevel));

msg.payload = {
    sensor_id: "bueiro_01",
    localizacao: "Vale do Anhangabau - SP",
    distancia_cm: parseFloat(dist.toFixed(1)),
    timestamp_epoch_ms: Date.now()
};

return msg;

// ========================================================================
// Converte payload do sensor MQTT para o schema do InfluxDB 2.x
// ========================================================================
let data = msg.payload;

// Leitura da distancia e cálculo da lamina d'agua
let distancia = typeof data.distancia_cm === "number" ? data.distancia_cm : 200.0;
let laminaAgua = 200.0 - distancia;
if (laminaAgua < 0) laminaAgua = 0.0;
let ocupacaoPct = parseFloat(((laminaAgua / 200.0) * 100.0).toFixed(1));

// Classificacao do status
let status = "NORMAL";
if (ocupacaoPct >= 80.0) status = "CRITICO";
else if (ocupacaoPct >= 50.0) status = "ATENCAO";

// Armazena a leitura mais recente na memoria para resposta instantanea no Telegram
global.set("last_reading", {
    distancia_cm: parseFloat(distancia.toFixed(1)),
    lamina_agua_cm: parseFloat(laminaAgua.toFixed(1)),
    ocupacao_pct: ocupacaoPct,
    status: status
});

// Objeto estruturado esperado pelo no 'influxdb out':
// msg.payload[0] -> Objeto de Fields (valores numericos)
// msg.payload[1] -> Objeto de Tags (metadados indexados)
msg.payload = [
    {
        distancia_cm: parseFloat(distancia.toFixed(1)),
        lamina_agua_cm: parseFloat(laminaAgua.toFixed(1)),
        ocupacao_pct: ocupacaoPct
    },
    {
        sensor_id: data.sensor_id || "bueiro_01",
        local: data.localizacao || "Vale do Anhangabau",
        status: status
    }
];

msg.measurement = "medicoes_pluviais";
return msg;

let savedChatId = global.get("telegram_chat_id");
if (savedChatId) {
  msg.payload.chatId = savedChatId;
}
return msg;

var opts = {
  reply_markup: JSON.stringify({
    "inline_keyboard": [[
      {
        "text": "🌊 Lâmina d'Água",
        "callback_data": "1"
      },
      {
        "text": "📊 Ocupação (%)",
        "callback_data": "2"
      },
      {
        "text": "📏 Distância (cm)",
        "callback_data": "3"
      }
    ]]
  })
};

let targetChatId = (msg.originalMessage && msg.originalMessage.chat) 
  ? msg.originalMessage.chat.id 
  : (msg.payload && msg.payload.chatId ? msg.payload.chatId : "8260527561");

// Salva o Chat ID globalmente para que o alerta de inatividade use automaticamente
global.set("telegram_chat_id", targetChatId);

msg.error = false;
msg.payload = {
  type: "message",
  content: "✅ Sistema Integrado de Monitoramento Pluvial (SIMP-SP) conectado!\n🆔 Seu Chat ID é: " + targetChatId + "\n\nSelecione a métrica desejada para consulta em tempo real:",
  options: opts,
  chatId: targetChatId
};

return [msg];

let cb = msg.callback || msg.payload || {};
let choice = String(cb.content || cb.data || "1");
let targetChatId = cb.chatId || (cb.message && cb.message.chat ? cb.message.chat.id : "8260527561");

// Busca ultima leitura da memoria ou usa valor padrao
let lastData = global.get("last_reading") || {
  lamina_agua_cm: 34.8,
  ocupacao_pct: 17.4,
  distancia_cm: 165.2
};

let data = (Array.isArray(msg.payload) && msg.payload.length > 0 && typeof msg.payload[0] === 'object') 
  ? Object.assign({}, lastData, msg.payload[0]) 
  : lastData;

let textResponse = "";
if (choice === "1") {
  textResponse = "🌊 Lâmina d'Água Atual: " + data.lamina_agua_cm + " cm";
} else if (choice === "2") {
  let pct = data.ocupacao_pct;
  let statusTag = pct >= 80 ? " 🔴 CRÍTICO" : (pct >= 50 ? " 🟡 ATENÇÃO" : " 🟢 NORMAL");
  textResponse = "📊 Ocupação da Galeria: " + pct + "%" + statusTag;
} else if (choice === "3") {
  textResponse = "📏 Distância Sensor-Água: " + data.distancia_cm + " cm";
} else {
  textResponse = "📊 Telemetria do Bueiro 01: " + data.ocupacao_pct + "% (" + data.lamina_agua_cm + " cm)";
}

msg.payload = {
  type: "message",
  content: textResponse,
  chatId: targetChatId
};

return msg;
